import originalCmsData from '../src/data/mockCmsData.js';
import { upgradeContent } from '../shared/content.js';
const mockCmsData = upgradeContent(originalCmsData);

const origin = 'http://127.0.0.1:5173';

/** Creates an isolated test-only account without default production credentials. */
async function fixture(t) {
  const store = createContentStore({ databasePath: ':memory:', seed: mockCmsData });
  t.after(() => store.close());
  const app = createApp({ contentStore: store });
  const password = randomBytes(24).toString('hex');
  await app.locals.adminStore.provision('test-admin', password);
  const agent = request.agent(app);
  const login = await agent.post('/api/admin/login').set('Origin', origin).send({ username: 'test-admin', password }).expect(200);
  return { store, app, agent, password, csrf: login.body.csrfToken, login };
}

test('login protects credentials, cookie flags, and authenticated reads', async t => {
  const { app, agent, login, password, store } = await fixture(t);
  const cookie = login.headers['set-cookie'][0];
  assert.match(cookie, /HttpOnly/);
  assert.match(cookie, /SameSite=Strict/);
  assert.equal(login.body.token, undefined);
  assert.equal(login.headers['cache-control'], 'no-store');
  assert.ok(!store.database.prepare('SELECT password_hash FROM admins').get().password_hash.includes(password));
  await request(app).get('/api/admin/content').expect(401);
  await request(app).post('/api/admin/login').set('Origin', origin).send({ username: 'test-admin', password: 'wrong' }).expect(401);
  await request(app).post('/api/admin/login').send({ username: 'test-admin', password }).expect(403);
  await agent.get('/api/admin/session').expect(200);
  await agent.get('/api/admin/content').expect(200);
});

test('publishing validates content, checks CSRF and versions, and refreshes public content', async t => {
  const { app, agent, csrf } = await fixture(t);
  const edited = structuredClone(mockCmsData);
  edited.about.title = 'Published by an admin';
  await agent.put('/api/admin/content').set('Origin', origin).send({ content: edited, version: 1 }).expect(403);
  const invalid = structuredClone(edited);
  invalid.navigation.items[0].href = 'javascript:alert(1)';
  await agent.put('/api/admin/content').set('Origin', origin).set('X-CSRF-Token', csrf).send({ content: invalid, version: 1 }).expect(400);
  const saved = await agent.put('/api/admin/content').set('Origin', origin).set('X-CSRF-Token', csrf).send({ content: edited, version: 1 }).expect(200);
  assert.equal(saved.body.version, 2);
  const published = await request(app).get('/api/content').expect(200);
  assert.equal(published.body.about.title, edited.about.title);
  await agent.put('/api/admin/content').set('Origin', origin).set('X-CSRF-Token', csrf).send({ content: mockCmsData, version: 1 }).expect(409);
  await agent.post('/api/admin/logout').set('Origin', origin).set('X-CSRF-Token', csrf).expect(204);
  await agent.get('/api/admin/content').expect(401);
});

test('expired sessions and inconsistent calculator values are rejected', async t => {
  const { agent, csrf, store } = await fixture(t);
  const invalid = structuredClone(mockCmsData);
  invalid.calculator.inputs[0].defaultValue = 9000;
  await agent.put('/api/admin/content').set('Origin', origin).set('X-CSRF-Token', csrf).send({ content: invalid, version: 1 }).expect(400);
  store.database.prepare('UPDATE sessions SET expires_at = 0').run();
  await agent.get('/api/admin/session').expect(401);
});